INSERT INTO {{META_DB}}.GOVT_RGLTRY_SamplingConfig (Project_Cd, Table_Nm, Run_Ty, Smpl_Desc, Src_Schema_Nm, Src_Table_Nm, Key_Columns_Txt, Scope_Sql_Txt, Run_Key_Txt, Diversity_Sql_Txt, Target_Ty, Target_Val, Smpl_Method_Cd, Rounding_Cd, Shortfall_Cd, Keep_Excluded_Ind, Tgt_Schema_Nm, Tgt_Table_Nm, Active_Ind)
VALUES ('UMCM', 'ODAG1', 'WKLY', 'ODAG1 weekly UM audit sample: 150 cases by functional area and determination', 'EXPORT_FEED_$ENV_T', 'SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1', 'AUTHZN_ID, SRC_DATA_KEY, AUTHZN_REVSN_NUM', 'SELECT * FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 WHERE BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows}', '{batch_id}', 'SELECT AUTHZN_ID, SRC_DATA_KEY, AUTHZN_REVSN_NUM, CASE WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''DRUGS - BIOLOGICS PART B'' THEN ''Part B'' WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) LIKE ''BEHAVIORAL HEALTH%'' OR (UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''OUTPATIENT'' AND UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 2))) = ''BEHAVIORAL HEALTH'') THEN ''BH'' WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''OUTPATIENT'' AND UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 2))) LIKE ''DURABLE MEDICAL EQUIPMENT%'' THEN ''DME'' WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''OUTPATIENT'' AND UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 2))) = ''HOME HEALTH SERVICES'' THEN ''HHC'' WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''INPATIENT'' AND (UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 2))) IN (''REHAB'', ''LTAC'') OR UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 2))) LIKE ''SNF%'') THEN ''IP PAC'' WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''OUTPATIENT'' THEN ''OP Medical'' WHEN UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''INPATIENT'' THEN ''IP Medical'' ELSE ''OTHER'' END AS area FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 WHERE BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows} AND UPPER(TRIM(AUTHZN_STAT_RSN)) = ''CONCURRENT REVIEW''', 'CNT', 150, 'RANKED', 'ROUND', 'TOPUP', 1, 'EXPORT_FEED_$ENV_T', 'SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1_Sample', 0);

INSERT INTO {{META_DB}}.GOVT_RGLTRY_SamplingRule (Rule_ID, Project_Cd, Table_Nm, Run_Ty, Rule_Class_Cd, Seq_Nbr, Rule_Nm, Rule_Sql_Txt, Rule_Desc)
VALUES (1, 'UMCM', '*', '*', 'PARAM', 1, 'batch_id', 'SELECT TOP 1 Btch_ID, Run_Ty AS batch_run_ty FROM HSABC_$ENV.GOVT_RGLTRY_RequestControl WHERE UPPER(TRIM(Project_Cd)) = UPPER(''{project_cd}'') AND UPPER(TRIM(Table_Nm)) = UPPER(''{table_nm}'') AND UPPER(TRIM(Run_Ty)) = UPPER(''{run_ty}'') GROUP BY Btch_ID, Run_Ty HAVING MIN(Batch_Close_Ind) = 1 ORDER BY SUBSTR(Btch_ID, 1, 8) DESC, CHARACTER_LENGTH(Btch_ID) DESC, Btch_ID DESC', 'Use the latest batch whose sources are all closed, with its run type');

