INSERT INTO {{META_DB}}.GOVT_RGLTRY_SamplingRule (Rule_ID, Project_Cd, Table_Nm, Run_Ty, Rule_Class_Cd, Seq_Nbr, Rule_Nm, Rule_Ty, Parent_Path_Txt, Max_Ty, Max_Val, Rule_Sql_Txt, Rule_Desc)
VALUES (22, 'UMCM', 'ODAG1', 'WKLY', 'CAP', 1, 'BH_MAX_8_PCT', 'QUERY', '*', 'PCT', 8, 'SELECT AUTHZN_ID, SRC_DATA_KEY, AUTHZN_REVSN_NUM FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 WHERE BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows} AND (UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) LIKE ''BEHAVIORAL HEALTH%'' OR (UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 1))) = ''OUTPATIENT'' AND UPPER(TRIM(STRTOK(NULLIF(TRIM(ISS_DESC), ''''), '','', 2))) = ''BEHAVIORAL HEALTH'')) AND COALESCE(UPPER(TRIM(AUTHZN_STAT_RSN)), '''') <> ''CONCURRENT REVIEW''', 'No more than 8% of the sample from behavioral health, top-up included; concurrent reviews do not count');

INSERT INTO {{META_DB}}.GOVT_RGLTRY_SamplingRule (Rule_ID, Project_Cd, Table_Nm, Run_Ty, Rule_Class_Cd, Seq_Nbr, Rule_Nm, Rule_Ty, Parent_Path_Txt, Max_Ty, Max_Val, Rule_Sql_Txt, Rule_Desc)
VALUES (23, 'UMCM', 'ODAG1', 'WKLY', 'CAP', 2, 'PER_CPT_CODE', 'PER_VALUE', '*', 'CNT', 3, 'SELECT AUTHZN_ID, SRC_DATA_KEY, AUTHZN_REVSN_NUM, NULLIF(OREPLACE(CPT_PROC_CD, '' '', ''''), '''') AS CPT_PROC_CD FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 WHERE BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows}', 'No more than 3 cases with the same list of procedure codes');

