VALUES (24, 'UMCM', 'ODAG1', 'WKLY', 'CAP', 3, 'OON_MAX_10', 'QUERY', '*', 'CNT', 10, 'SELECT AUTHZN_ID, SRC_DATA_KEY, AUTHZN_REVSN_NUM FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 WHERE BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows} AND UPPER(TRIM(SVC_PROV_TY)) = ''NON PAR''', 'No more than 10 out-of-network cases in the whole sample');

INSERT INTO {{META_DB}}.GOVT_RGLTRY_SamplingRule (Rule_ID, Project_Cd, Table_Nm, Run_Ty, Rule_Class_Cd, Seq_Nbr, Rule_Nm, Rule_Ty, Parent_Path_Txt, Max_Ty, Max_Val, Rule_Sql_Txt, Rule_Desc)
VALUES (25, 'UMCM', 'ODAG1', 'WKLY', 'CAP', 4, 'CAPPED_ROUTES_MAX_5', 'QUERY', '*', 'CNT', 5, 'SELECT o.AUTHZN_ID, o.SRC_DATA_KEY, o.AUTHZN_REVSN_NUM FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 o WHERE o.BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(o.RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows} AND EXISTS (SELECT 1 FROM HSLABBOSS.UMCM_SHRPA_PROCEDURE_CODES s WHERE {current_rows:s} AND (UPPER(OREPLACE(OREPLACE(s.Clinical_Mgt_Route, '' '', ''''), ''-'', '''')) LIKE ''%NOPA%APPROVEPAR%PENDOON%'' OR UPPER(OREPLACE(OREPLACE(s.Clinical_Mgt_Route, '' '', ''''), ''-'', '''')) LIKE ''%FASTCERT%APPROVEPAR%PENDOON%'' OR UPPER(OREPLACE(OREPLACE(s.Clinical_Mgt_Route, '' '', ''''), ''-'', '''')) LIKE ''%GENETIC%ADMINISTRATIVELYAPPROVE%NONETWORKREVIEW%'' OR UPPER(OREPLACE(OREPLACE(s.Clinical_Mgt_Route, '' '', ''''), ''-'', '''')) LIKE ''%IPOLIST%APPROVEANDPLACEINCONCURRENTREVIEW%'') AND POSITION('','' || UPPER(TRIM(s.PROCEDURE_CODE)) || '','' IN '','' || UPPER(OREPLACE(o.CPT_PROC_CD, '' '', '''')) || '','') > 0)', 'No more than 5 cases in the whole sample with a procedure code routed as NOPA, Genetic, IPO List or Fast Cert (Clinical_Mgt_Route in SHRPA)');

INSERT INTO {{META_DB}}.GOVT_RGLTRY_SamplingRule (Rule_ID, Project_Cd, Table_Nm, Run_Ty, Rule_Class_Cd, Seq_Nbr, Rule_Nm, Rule_Ty, Level_Nbr, Parent_Path_Txt, Max_Ty, Max_Val, Rule_Sql_Txt, Rule_Desc)
VALUES (26, 'UMCM', 'ODAG1', 'WKLY', 'CAP', 5, 'EXPEDITED_MAX_75_PCT', 'PER_BUCKET', 1, '*', 'PCT', 75, 'SELECT AUTHZN_ID, SRC_DATA_KEY, AUTHZN_REVSN_NUM FROM EXPORT_FEED_$ENV_T.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 WHERE BTCH_ID = ''{batch_id}'' AND UPPER(TRIM(RUN_TY)) = UPPER(''{batch_run_ty}'') AND {current_rows} AND UPPER(TRIM(AUTHZN_REQ_STD_OR_EXPDT_IND)) = ''E''', 'No more than 75% expedited cases in each area, with IPRF, LTAC and SNF counted separately');
